// ── Build product options ────────────────────────────────────
function buildOptions(selected, level) {
  const lvl = level || currentLevel || 'Salon';
  return PRODUCTS.map(p => {
    const code = p.color_code ? `[${p.color_code}] ` : '';
    const retail = parseFloat(p.price_retail) || parseFloat(p.price);
    const salon  = parseFloat(p.price);
    const wholesaleDiscount = parseFloat(p.discount_wholesale) || 0;
    const wholesale = Math.round(salon * (1 - wholesaleDiscount / 100) * 100) / 100;
    const price = lvl === 'Retail' ? retail : lvl === 'Wholesale' ? wholesale : salon;
    return `<option value="${p.barcode}" ${p.barcode === selected ? 'selected' : ''} data-price="${price}">${p.brand} ${code}${p.name} — $${price.toFixed(2)}</option>`;
  }).join('');
}

// ── Add a product line ───────────────────────────────────────
let lineCount = 0;
function addProductLine(barcode = '', qty = 1) {
  lineCount++;
  const id = lineCount;
  const container = document.getElementById('product-lines');
  const div = document.createElement('div');
  div.className = 'product-row';
  div.id = 'line-' + id;
  div.dataset.barcode = barcode;
  const product = PRODUCTS.find(p => p.barcode === barcode);
  const price = product ? getPrice(product) : 0;
  const label = product ? `${product.brand} [${product.color_code || '—'}] ${product.name} — $${price.toFixed(2)}` : '';
  const priceLabel = price > 0 ? `$${price.toFixed(2)}` : '';
  div.innerHTML = `
    <div class="product-row-top">
      <div class="product-line-label">${label.replace(/ — \$[\d.]+/, '')}</div>
      <span class="product-line-price" id="price-label-${id}">${priceLabel}</span>
    </div>
    <div class="product-row-bottom">
      <button onclick="changeQty(${id}, -1)" style="width:32px; height:32px; border:1px solid var(--border); border-radius:var(--radius); background:var(--surface); font-size:18px; cursor:pointer; display:flex; align-items:center; justify-content:center; color:var(--text);">−</button>
      <input type="number" id="qty-${id}" value="${qty}" min="1" max="999" step="1" oninput="recalcTotal()">
      <button onclick="changeQty(${id}, 1)" style="width:32px; height:32px; border:1px solid var(--border); border-radius:var(--radius); background:var(--surface); font-size:18px; cursor:pointer; display:flex; align-items:center; justify-content:center; color:var(--text);">+</button>
      <label style="display:flex; align-items:center; gap:5px; font-size:13px; color:#16a34a; cursor:pointer; margin-left:4px;">
        <input type="checkbox" id="free-${id}" onchange="toggleFree(${id})" style="accent-color:#16a34a; width:16px; height:16px;"> Gratis
      </label>
      <button class="remove-btn" onclick="removeLine(${id})" aria-label="Eliminar" style="margin-left:auto;">×</button>
    </div>
  `;
  container.appendChild(div);
  recalcTotal();
}

function removeLine(id) {
  const el = document.getElementById('line-' + id);
  if (el) el.remove();
  recalcTotal();
}

function changeQty(id, delta) {
  const input = document.getElementById('qty-' + id);
  if (!input) return;
  const newVal = Math.max(1, Math.min(999, (parseInt(input.value) || 1) + delta));
  input.value = newVal;
  recalcTotal();
}

function toggleFree(id) {
  const freeCheck = document.getElementById('free-' + id);
  const priceLabel = document.getElementById('price-label-' + id);
  const row = document.getElementById('line-' + id);
  if (!row) return;
  const barcode = row.dataset.barcode;
  const product = PRODUCTS.find(p => p.barcode === barcode);
  if (freeCheck && freeCheck.checked) {
    if (priceLabel) { priceLabel.textContent = 'FREE'; priceLabel.style.color = '#16a34a'; }
    row.style.borderColor = '#bbf7d0';
    row.style.background = '#f0fdf4';
  } else {
    const price = product ? getPrice(product) : 0;
    if (priceLabel) { priceLabel.textContent = '$' + price.toFixed(2); priceLabel.style.color = 'var(--gold)'; }
    row.style.borderColor = '';
    row.style.background = '';
  }
  recalcTotal();
}

// ── Permit change ────────────────────────────────────────────
function onPermitChange() {
  const permit = document.getElementById('permit').value.trim();
  const note = document.getElementById('permit-note');
  const taxToggle = document.getElementById('tax-toggle');
  const taxRow = document.getElementById('tax-toggle-row');
  if (permit.length > 0) {
    note.textContent = '✓ Cliente exento de tax';
    note.style.color = 'var(--success)';
    taxToggle.checked = false;
    taxRow.style.opacity = '0.4';
    taxRow.style.pointerEvents = 'none';
  } else {
    note.textContent = 'Sin permit — verifica si aplica tax';
    note.style.color = 'var(--warning)';
    taxRow.style.opacity = '1';
    taxRow.style.pointerEvents = 'auto';
  }
  recalcTotal();
}

// ── Recalculate totals ───────────────────────────────────────
function recalcTotal() {
  let subtotal = 0;
  document.querySelectorAll('#product-lines .product-row').forEach(row => {
    const qty = row.querySelector('input[type=number]');
    const barcode = row.dataset.barcode;
    if (barcode && qty) {
      const product = PRODUCTS.find(p => p.barcode === barcode);
      if (product) {
        const lineId = row.id.replace('line-', '');
        const freeCheck = document.getElementById(`free-${lineId}`);
        const isFree = freeCheck && freeCheck.checked;
        subtotal += isFree ? 0 : getPrice(product) * (parseInt(qty.value) || 0);
      }
    }
  });
  const hasShipping = document.getElementById('shipping-toggle').checked;
  const hasTax = document.getElementById('tax-toggle').checked;
  const taxRate = parseFloat(document.getElementById('tax-rate').value) || 0;
  const shippingAmt = hasShipping ? SHIPPING : 0;
  const taxAmt = hasTax ? subtotal * (taxRate / 100) : 0;

  // Manual discount
  const discountType = document.getElementById('discount-type')?.value || 'pct';
  const discountVal = parseFloat(document.getElementById('discount-val')?.value) || 0;
  const discountAmt = discountType === 'pct' ? subtotal * (discountVal / 100) : Math.min(discountVal, subtotal);
  const discountReason = document.getElementById('discount-reason')?.value.trim() || '';

  const total = Math.max(0, subtotal + shippingAmt + taxAmt - discountAmt);

  document.getElementById('sum-products').textContent = '$' + subtotal.toFixed(2);
  document.getElementById('sum-shipping-row').style.display = hasShipping ? 'flex' : 'none';
  document.getElementById('sum-tax-row').style.display = hasTax ? 'flex' : 'none';
  document.getElementById('sum-tax-label').textContent = 'Tax (' + taxRate.toFixed(2) + '%)';
  document.getElementById('sum-tax-amount').textContent = '$' + taxAmt.toFixed(2);
  const discRow = document.getElementById('sum-discount-row');
  if (discRow) {
    discRow.style.display = discountAmt > 0 ? 'flex' : 'none';
    document.getElementById('sum-discount-label').textContent = discountReason ? `Discount (${discountReason})` : 'Discount';
    document.getElementById('sum-discount-amount').textContent = '-$' + discountAmt.toFixed(2);
  }
  document.getElementById('order-total').textContent = '$' + total.toFixed(2);
  document.getElementById('tax-rate-row').style.display = hasTax ? 'block' : 'none';
}

