// ── Admin login ──────────────────────────────────────────────
function showLoginModal() {
  document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
  document.getElementById('login-modal').style.display = 'flex';
  document.getElementById('login-user').value = '';
  document.getElementById('login-pass').value = '';
  document.getElementById('login-error').textContent = '';
  setTimeout(() => document.getElementById('login-user').focus(), 100);
}

function hideLoginModal() {
  if (!currentRole) return; // Don't hide if not authenticated
  document.getElementById('login-modal').style.display = 'none';
}

async function doLogin() {
  const email = document.getElementById('login-user').value.trim();
  const pass = document.getElementById('login-pass').value;
  const errEl = document.getElementById('login-error');
  errEl.textContent = '';
  if (!email || !pass) { errEl.textContent = 'Ingresa tu email y contraseña.'; return; }
  const btn = document.querySelector('#login-modal .submit-btn');
  btn.textContent = 'Entrando...'; btn.disabled = true;
  try {
    const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'apikey': SUPABASE_KEY },
      body: JSON.stringify({ email, password: pass })
    });
    const data = await res.json();
    if (!res.ok) { errEl.textContent = 'Email o contraseña incorrectos.'; return; }
    localStorage.setItem('sb_token', data.access_token);
    localStorage.setItem('sb_uid', data.user.id);
    await loadProfileAndApply(data.access_token, data.user.id, errEl);
  } catch(e) { errEl.textContent = 'Error de conexion.'; }
  finally { btn.textContent = 'Entrar →'; btn.disabled = false; }
}

async function loadProfileAndApply(token, uid, errEl) {
  const profile = await fetch(`${SUPABASE_URL}/rest/v1/profiles?id=eq.${uid}&select=*`, {
    headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${token}` }
  }).then(r => r.json());
  if (!profile || !profile.length) {
    if (errEl) errEl.textContent = 'Cuenta sin rol asignado. Contacta al admin.';
    localStorage.removeItem('sb_token'); localStorage.removeItem('sb_uid'); return;
  }
  currentUser = profile[0]; currentRole = profile[0].role;
  isAdmin = currentRole === 'admin';
  isDelivery = currentRole === 'delivery';
  hideLoginModal();
  startInactivityWatcher();

  // Auto-fill seller name in Nueva Orden and POS
  const sellerInput = document.getElementById('seller-name');
  const sellerSelect = document.getElementById('seller-name-select');
  const posSellerInput = document.getElementById('pos-seller-name');
  if (posSellerInput && profile[0].name) posSellerInput.value = profile[0].name;

  if (currentRole === 'seller') {
    // Seller: readonly input with their name
    if (sellerInput && profile[0].name) {
      sellerInput.value = profile[0].name;
      sellerInput.readOnly = true;
      sellerInput.style.background = 'var(--surface-2)';
      sellerInput.style.color = 'var(--text-muted)';
      sellerInput.style.cursor = 'default';
    }
    if (sellerSelect) sellerSelect.style.display = 'none';
    const posSellerSelect = document.getElementById('pos-seller-select');
    if (posSellerSelect) posSellerSelect.style.display = 'none';
  } else if (isAdmin) {
    // Admin: show dropdown with all sellers in both Nueva Orden and POS
    if (sellerInput) sellerInput.style.display = 'none';

    supabase('profiles?select=name,role&order=name').then(sellers => {
      if (!sellers) return;
      const opts = '<option value="">— Seleccionar vendedor —</option>' +
        sellers.filter(s => s.name).map(s =>
          `<option value="${s.name}">${s.name}${s.role === 'admin' ? ' (admin)' : ''}</option>`
        ).join('');

      // Nueva Orden dropdown
      if (sellerSelect) {
        sellerSelect.style.display = 'block';
        sellerSelect.innerHTML = opts;
        if (profile[0].name) { sellerSelect.value = profile[0].name; }
        document.getElementById('seller-name').value = profile[0].name || '';
      }

      // POS dropdown
      const posSellerSelect = document.getElementById('pos-seller-select');
      if (posSellerSelect) {
        posSellerSelect.style.display = 'block';
        posSellerSelect.innerHTML = opts;
        if (profile[0].name) { posSellerSelect.value = profile[0].name; }
        document.getElementById('pos-seller-name').value = profile[0].name || '';
        document.getElementById('pos-seller-name').style.display = 'none';
      }
    });
  }

  // Show Mi Progreso tab for sellers
  const miProgresoBtn = document.getElementById('tab-miprogreso-btn');
  if (miProgresoBtn) miProgresoBtn.style.display = currentRole === 'seller' ? '' : 'none';

  // Load products for all roles (needed for order form and POS)
  if (!PRODUCTS || PRODUCTS.length === 0) {
    dbFetchProducts().then(prods => { PRODUCTS = prods; }).catch(e => console.error('Products load error:', e));
  }

  if (isAdmin) {
    showAdminView();
  } else if (isDelivery) {
    document.querySelectorAll('.tab').forEach(t => { t.style.display = t.id === 'tab-delivery-btn' ? '' : 'none'; });
    showTab('delivery');
  } else if (currentRole === 'seller') {
    document.querySelectorAll('.tab').forEach(t => { t.style.display = ['tab-vendedor-btn','tab-pos-btn','tab-miprogreso-btn'].includes(t.id) ? '' : 'none'; });
    showTab('vendedor');
  }
}

async function checkSession() {
  const token = localStorage.getItem('sb_token');
  const uid = localStorage.getItem('sb_uid');
  if (!token || !uid) return;
  try {
    const res = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
      headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${token}` }
    });
    if (!res.ok) { localStorage.removeItem('sb_token'); localStorage.removeItem('sb_uid'); return; }
    await loadProfileAndApply(token, uid, null);
  } catch(e) { console.error(e); }
}

async function doLogout() {
  stopInactivityWatcher();
  const token = localStorage.getItem('sb_token');
  if (token) await fetch(`${SUPABASE_URL}/auth/v1/logout`, { method:'POST', headers:{'apikey':SUPABASE_KEY,'Authorization':`Bearer ${token}`} }).catch(()=>{});
  localStorage.removeItem('sb_token'); localStorage.removeItem('sb_uid');
  currentUser = null; currentRole = null; isAdmin = false; isDelivery = false;
  // Hide all sections
  document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
  document.querySelectorAll('.tab').forEach(t => { t.classList.remove('active'); t.style.display = ''; });
  document.getElementById('logout-btn').style.display = 'none';
  // Clear sensitive data from view
  document.getElementById('orders-list') && (document.getElementById('orders-list').innerHTML = '');
  showLoginModal();
}



