// ── Customer level ───────────────────────────────────────────
function setLevel(level) {
  currentLevel = level;
  document.getElementById('level-select').value = level;
  updateLevelBadge();
  if (allVariations.length > 0) renderVariations(allVariations);
}

function updateLevelBadge() {
  const badge = document.getElementById('level-badge');
  const colors = { Retail: 'badge-nueva', Salon: 'badge-lista', Wholesale: 'badge-proceso' };
  badge.textContent = currentLevel;
  badge.className = 'level-badge ' + (colors[currentLevel] || '');
}

// ── Stepped product selector ─────────────────────────────────
let stepState = { brand: null, category: null, variation: null, qty: 1 };
let allVariations = [];

function initSteppedSelector() {
  const brands = [...new Set(PRODUCTS.map(p => p.brand))].sort();
  const container = document.getElementById('brand-options');
  container.innerHTML = brands.map(b => {
    const logo = BRAND_LOGOS[b];
    const img = logo ? `<img src="${logo}" alt="${b}" style="height:28px; max-width:80px; object-fit:contain; display:block; margin:0 auto 2px;">` : '';
    return `<button class="brand-chip step-chip" onclick="selectBrand('${b}')">${img}<span>${b}</span></button>`;
  }).join('');
  initDragScroll(container);
}

function selectBrand(brand) {
  stepState = { brand, category: null, variation: null, qty: 1 };
  document.querySelectorAll('#brand-options .step-chip').forEach(b => b.classList.remove('active'));
  document.querySelector(`#brand-options .step-chip[onclick="selectBrand('${brand}')"]`).classList.add('active');

  const categories = [...new Set(PRODUCTS.filter(p => p.brand === brand).map(p => p.category))].sort();
  const container = document.getElementById('category-options');
  container.innerHTML = categories.map(c => `
    <button class="step-chip" onclick="selectCategory('${c}')">${c}</button>
  `).join('');
  initDragScroll(container);

  document.getElementById('step-category').style.display = 'block';
  document.getElementById('step-variation').style.display = 'none';
  document.getElementById('step-qty').style.display = 'none';
  document.getElementById('variation-search').value = '';
}

function selectCategory(category) {
  stepState.category = category;
  document.querySelectorAll('#category-options .step-chip').forEach(b => b.classList.remove('active'));
  document.querySelector(`#category-options .step-chip[onclick="selectCategory('${category}')"]`).classList.add('active');

  allVariations = PRODUCTS.filter(p => p.brand === stepState.brand && p.category === category);
  renderVariations(allVariations);
  document.getElementById('step-variation').style.display = 'block';
  document.getElementById('step-qty').style.display = 'none';
  document.getElementById('variation-search').value = '';
}

function renderVariations(variations) {
  const container = document.getElementById('variation-options');
  container.innerHTML = variations.map(p => {
    const code = p.color_code && p.color_code !== 'null' ? p.color_code : '—';
    const price = getPrice(p);
    return `
    <button class="variation-chip" onclick="selectVariation('${p.barcode}')">
      <span class="variation-code">${code}</span>
      <span class="variation-name">${p.name}</span>
      <span class="variation-price">$${price.toFixed(2)}</span>
    </button>
  `}).join('');
}

function filterVariations(query) {
  const q = query.toLowerCase();
  const filtered = q.length < 1 ? allVariations : allVariations.filter(p =>
    p.name.toLowerCase().includes(q) ||
    (p.color_code && p.color_code.toLowerCase().includes(q))
  );
  renderVariations(filtered);
}

function selectVariation(barcode) {
  stepState.variation = barcode;
  stepState.qty = 1;
  document.querySelectorAll('.variation-chip').forEach(b => b.classList.remove('active'));
  document.querySelector(`.variation-chip[onclick="selectVariation('${barcode}')"]`).classList.add('active');
  document.getElementById('qty-display').textContent = 1;
  document.getElementById('step-qty').style.display = 'block';
  document.getElementById('step-qty').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function posStepChangeQty(delta) {
  stepState.qty = Math.max(1, (stepState.qty || 1) + delta);
  document.getElementById('qty-display').textContent = stepState.qty;
}

function confirmAddProduct() {
  const product = PRODUCTS.find(p => p.barcode === stepState.variation);
  if (!product) return;

  // Check if product already in list — if so, update qty
  const existing = document.querySelector(`.product-row[data-barcode="${product.barcode}"]`);
  if (existing) {
    const qtyInput = existing.querySelector('input[type=number]');
    qtyInput.value = parseInt(qtyInput.value) + stepState.qty;
    recalcTotal();
    showToast(`✓ +${stepState.qty} ${product.name}`);
  } else {
    addProductLine(product.barcode, stepState.qty);
    showToast(`✓ ${product.name} agregado`);
  }

  // Reset variation and qty step, keep brand+category
  stepState.variation = null;
  stepState.qty = 1;
  document.getElementById('step-qty').style.display = 'none';
  document.getElementById('qty-display').textContent = 1;
  document.querySelectorAll('.variation-chip').forEach(b => b.classList.remove('active'));
}

function resetSteppedSelector() {
  stepState = { brand: null, category: null, variation: null, qty: 1 };
  document.getElementById('step-category').style.display = 'none';
  document.getElementById('step-variation').style.display = 'none';
  document.getElementById('step-qty').style.display = 'none';
  document.querySelectorAll('.step-chip, .variation-chip').forEach(b => b.classList.remove('active'));
  document.getElementById('variation-search').value = '';
}


// ── Order search ──────────────────────────────────────────────
function searchOrders(query) {
  const q = query.toLowerCase().trim();
  if (!q) {
    const filtered = currentFilter === 'all' ? allOrders : allOrders.filter(o => o.status === currentFilter);
    renderOrders(filtered);
    return;
  }
  const results = allOrders.filter(o =>
    o.client.toLowerCase().includes(q) ||
    o.business.toLowerCase().includes(q) ||
    o.phone.includes(q) ||
    String(o.id).includes(q) ||
    (o.seller && o.seller.toLowerCase().includes(q))
  );
  renderOrders(results);
  document.getElementById('order-count-label').textContent = results.length + ' resultado' + (results.length !== 1 ? 's' : '');
}

// ── Duplicate order ───────────────────────────────────────────
function duplicateOrder(id) {
  const order = allOrders.find(o => o.id === id);
  if (!order) return;

  // Switch to nueva orden tab and prefill
  showTab('vendedor');
  setTimeout(() => {
    document.getElementById('client-name').value = order.client;
    document.getElementById('business-name').value = order.business;
    document.getElementById('phone').value = order.phone;
    document.getElementById('permit').value = order.permit || '';
    document.getElementById('address').value = order.address;
    document.getElementById('email').value = order.email || '';
    document.getElementById('notes').value = order.notes || '';
    onPermitChange();

    // Reset product lines
    document.getElementById('product-lines').innerHTML = '';
    lineCount = 0;
    resetSteppedSelector();

    // Add products from original order
    order.lines.forEach(l => addProductLine(l.barcode, l.qty));
    recalcTotal();
    showToast('✓ Orden duplicada — revisa y envía');
  }, 100);
}

// ── Customer search / autofill ───────────────────────────────
let allCustomers = [];

async function loadCustomersList() {
  try {
    allCustomers = await dbFetchCustomers();
  } catch(e) {
    allCustomers = [];
  }
}

function searchCustomers(query) {
  const box = document.getElementById('customer-suggestions');
  if (!query || query.length < 2) { box.style.display = 'none'; return; }

  const q = query.toLowerCase();
  const matches = allCustomers.filter(c =>
    c.name.toLowerCase().includes(q) ||
    c.business.toLowerCase().includes(q) ||
    c.phone.includes(q)
  ).slice(0, 6);

  if (matches.length === 0) { box.style.display = 'none'; return; }

  box.innerHTML = matches.map(c => `
    <div class="suggestion-item" onclick="fillCustomer(${c.id})">
      <div class="suggestion-name">${c.name}</div>
      <div class="suggestion-detail">${c.business} · ${c.phone}</div>
    </div>
  `).join('');
  box.style.display = 'block';
}

function fillCustomer(id) {
  const c = allCustomers.find(x => x.id === id);
  if (!c) return;
  document.getElementById('client-name').value = c.name;
  document.getElementById('business-name').value = c.business;
  document.getElementById('phone').value = c.phone;
  document.getElementById('permit').value = c.permit || '';
  document.getElementById('address').value = c.address || '';
  document.getElementById('email').value = c.email || '';
  document.getElementById('customer-search').value = `${c.name} — ${c.business}`;
  document.getElementById('customer-suggestions').style.display = 'none';

  // Set level from customer profile
  currentLevel = c.level || 'Salon';
  document.getElementById('level-select').value = currentLevel;
  updateLevelBadge();
  if (allVariations.length > 0) renderVariations(allVariations);
  onPermitChange();
}

// Close suggestions when clicking outside
document.addEventListener('click', e => {
  if (!e.target.closest('#customer-search') && !e.target.closest('#customer-suggestions')) {
    const box = document.getElementById('customer-suggestions');
    if (box) box.style.display = 'none';
  }
});



// ── Catalog ───────────────────────────────────────────────────
let editingProductId = null;
let catalogFilter = 'all';

window.loadCatalog = async function loadCatalog() {
  const list = document.getElementById('catalog-list');
  if (!list) return;
  list.innerHTML = `<div class="empty-state"><div class="empty-icon">⏳</div>Cargando...</div>`;
  try {
    const allProds = await supabase('products?select=*&order=brand,category,name');
    if (!allProds || allProds.length === 0) {
      list.innerHTML = `<div class="empty-state"><div class="empty-icon">📦</div>No hay productos</div>`;
      return;
    }
    allProds.sort((a,b) => a.brand.localeCompare(b.brand) || a.name.localeCompare(b.name));
    window._catalogProducts = allProds;
    window._catalogBrand = '';
    window._catalogCat = '';

    // Brand chips
    const brands = [...new Set(allProds.map(p => p.brand))].sort();
    const cats = [...new Set(allProds.map(p => p.category))].sort();

    const brandChipsEl = document.getElementById('catalog-brand-chips');
    const catChipsEl = document.getElementById('catalog-cat-chips');
    const brandFilterEl = document.getElementById('catalog-brand-filter');

    if (brandChipsEl) brandChipsEl.innerHTML = brands.map(b =>
      `<button class="catalog-brand-chip filter-chip" data-brand="${b}" onclick="setCatalogBrand('${b}')">${b}</button>`
    ).join('');

    if (brandFilterEl) brandFilterEl.innerHTML = brands.map(b =>
      `<button class="catalog-brand-chip filter-chip" data-brand="${b}" onclick="setCatalogBrand('${b}')">${b}</button>`
    ).join('');

    // Category chips hidden until a brand is selected
    if (catChipsEl) catChipsEl.innerHTML = '';

    populateDataLists(allProds);
    renderCatalog(allProds);
  } catch(e) {
    list.innerHTML = `<div class="empty-state"><div class="empty-icon">❌</div>Error cargando catálogo</div>`;
    console.error(e);
  }
}

function renderCatalogBrandFilter(products) {
  const brands = ['all', ...new Set(products.map(p => p.brand))];
  const container = document.getElementById('catalog-brand-filter');
  container.innerHTML = brands.map(b => `
    <button class="filter-chip ${b === catalogFilter ? 'active' : ''}" onclick="setCatalogFilter('${b}', this)">
      ${b === 'all' ? 'Todas las marcas' : b}
    </button>
  `).join('');
}

function setCatalogFilter(brand, btn) {
  catalogFilter = brand;
  document.querySelectorAll('#catalog-brand-filter .filter-chip').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  loadCatalog();
}

function populateDataLists(products) {
  const brands = [...new Set(products.map(p => p.brand))];
  const categories = [...new Set(products.map(p => p.category))];
  document.getElementById('brand-list').innerHTML = brands.map(b => `<option value="${b}">`).join('');
  document.getElementById('category-list').innerHTML = categories.map(c => `<option value="${c}">`).join('');
}

function renderCatalog(allProducts) {
  const list = document.getElementById('catalog-list');
  const countLabel = document.getElementById('catalog-count-label');
  if (!allProducts || !list) return;

  const searchVal = (document.getElementById('catalog-search') ? document.getElementById('catalog-search').value : '').toLowerCase();
  const brandFilter = window._catalogBrand || '';
  const catFilter = window._catalogCat || '';

  let filtered = allProducts;
  if (brandFilter) filtered = filtered.filter(p => p.brand === brandFilter);
  if (catFilter) filtered = filtered.filter(p => p.category === catFilter);
  if (searchVal) filtered = filtered.filter(p =>
    (p.name || '').toLowerCase().includes(searchVal) ||
    (p.color_code || '').toLowerCase().includes(searchVal) ||
    (p.barcode || '').toLowerCase().includes(searchVal)
  );

  if (countLabel) countLabel.textContent = `${filtered.length} productos`;

  if (!filtered.length) {
    list.innerHTML = '<div class="empty-state"><div class="empty-icon">🔍</div>Sin resultados</div>';
    return;
  }

  // Select all header
  const selectAllRow = `<div style="display:flex; align-items:center; gap:10px; padding:6px 0; margin-bottom:4px; border-bottom:1px solid var(--border);">
    <input type="checkbox" id="catalog-select-all" onchange="toggleSelectAll(this.checked)" style="width:16px; height:16px; accent-color:var(--gold); flex-shrink:0; cursor:pointer;">
    <span style="font-size:12px; color:var(--text-muted);">Seleccionar todos (${filtered.length})</span>
  </div>`;

  list.innerHTML = selectAllRow + filtered.map(p => {
    const wsPrice = p.price * (1 - (p.discount_wholesale || 0) / 100);
    return `<div class="catalog-item" style="display:flex; align-items:center; gap:10px; flex-wrap:wrap; padding:10px 12px; border:1px solid var(--border); border-radius:var(--radius); background:var(--surface); margin-bottom:6px;">
      <input type="checkbox" class="catalog-check" data-id="${p.id}" onchange="updateBulkBar()" style="width:16px; height:16px; accent-color:var(--gold); flex-shrink:0; cursor:pointer;">
      <div style="flex:1; min-width:160px;">
        <div style="display:flex; align-items:center; gap:8px;">
          ${p.color_code ? `<span style="font-size:15px; font-weight:700; color:var(--gold); min-width:36px;">[${p.color_code}]</span>` : ''}
          <span style="font-size:13px; font-weight:600; color:var(--text);">${p.name}</span>
        </div>
        <div style="font-size:11px; color:var(--text-faint); margin-top:2px;">${p.barcode} · <span style="color:var(--text-muted);">${p.brand}</span></div>
      </div>
      <div style="display:flex; gap:6px; align-items:center; flex-wrap:wrap; flex-shrink:0;">
        <span style="font-size:11px; background:var(--surface-2); border:1px solid var(--border); border-radius:4px; padding:3px 8px;">Salon <strong>$${p.price.toFixed(2)}</strong></span>
        <span style="font-size:11px; background:var(--surface-2); border:1px solid var(--border); border-radius:4px; padding:3px 8px;">Retail <strong>$${(p.price_retail||0).toFixed(2)}</strong></span>
        <span style="font-size:11px; background:var(--surface-2); border:1px solid var(--border); border-radius:4px; padding:3px 8px;">WS <strong>$${wsPrice.toFixed(2)}</strong></span>
        <button onclick="editProduct(${p.id})" style="font-size:11px; padding:3px 8px; border:1px solid var(--border); border-radius:var(--radius); background:none; cursor:pointer; color:var(--text-muted);">✏️</button>
        <button onclick="toggleProduct(${p.id}, ${!p.active})" style="font-size:11px; padding:3px 8px; border:1px solid var(--border); border-radius:var(--radius); background:none; cursor:pointer; color:${p.active ? '#16a34a' : '#dc2626'};">${p.active ? '✓' : '✗'}</button>
      </div>
    </div>`;
  }).join('');
}

function setCatalogBrand(brand) {
  window._catalogBrand = window._catalogBrand === brand ? '' : brand;
  window._catalogCat = ''; // reset category when switching brand

  document.querySelectorAll('.catalog-brand-chip').forEach(c => {
    c.classList.toggle('active', c.dataset.brand === window._catalogBrand);
  });

  const products = window._catalogProducts || [];
  const catChipsEl = document.getElementById('catalog-cat-chips');
  if (catChipsEl) {
    if (window._catalogBrand) {
      const cats = [...new Set(products.filter(p => p.brand === window._catalogBrand).map(p => p.category))].sort();
      catChipsEl.innerHTML = cats.map(c =>
        `<button class="catalog-cat-chip filter-chip" data-cat="${c}" onclick="setCatalogCat('${c}')">${c}</button>`
      ).join('');
    } else {
      catChipsEl.innerHTML = '';
    }
  }

  renderCatalog(products);
}

function setCatalogCat(cat) {
  window._catalogCat = window._catalogCat === cat ? '' : cat;
  document.querySelectorAll('.catalog-cat-chip').forEach(c => {
    const active = c.dataset.cat === window._catalogCat;
    c.classList.toggle('active', active);
  });
  renderCatalog(window._catalogProducts || []);
}



function calcWholesaleDiscount() {
  const salon = parseFloat(document.getElementById('pm-price').value) || 0;
  const ws = parseFloat(document.getElementById('pm-price-wholesale').value) || 0;
  if (salon > 0 && ws > 0) {
    const disc = ((1 - ws / salon) * 100).toFixed(2);
    document.getElementById('pm-discount-wholesale').value = disc;
  }
}

function calcWholesalePrice() {
  const salon = parseFloat(document.getElementById('pm-price').value) || 0;
  const disc = parseFloat(document.getElementById('pm-discount-wholesale').value) || 0;
  if (salon > 0) {
    document.getElementById('pm-price-wholesale').value = (salon * (1 - disc / 100)).toFixed(2);
  }
}

function editProduct(id) {
  const p = (window._catalogProducts || []).find(p => p.id === id);
  if (!p) return;
  editingProductId = id;
  document.getElementById('product-modal-title').textContent = 'Editar producto';
  document.getElementById('pm-brand').value = p.brand || '';
  document.getElementById('pm-category').value = p.category || '';
  document.getElementById('pm-code').value = p.color_code || '';
  document.getElementById('pm-barcode').value = p.barcode || '';
  document.getElementById('pm-name').value = p.name || '';
  document.getElementById('pm-price').value = p.price || '';
  document.getElementById('pm-price-retail').value = p.price_retail || '';
  document.getElementById('pm-discount-wholesale').value = p.discount_wholesale || '';
  const wsPrice = p.price && p.discount_wholesale ? (p.price * (1 - p.discount_wholesale / 100)).toFixed(4) : '';
  document.getElementById('pm-price-wholesale').value = wsPrice ? parseFloat(wsPrice) : '';
  document.getElementById('pm-active').checked = p.active !== false;
  document.getElementById('product-modal').style.display = 'flex';
}

function openAddProduct() {
  editingProductId = null;
  document.getElementById('product-modal-title').textContent = 'Nuevo producto';
  document.getElementById('pm-brand').value = '';
  document.getElementById('pm-category').value = '';
  document.getElementById('pm-code').value = '';
  document.getElementById('pm-barcode').value = '';
  document.getElementById('pm-name').value = '';
  document.getElementById('pm-price-retail').value = '';
  document.getElementById('pm-price').value = '';
  document.getElementById('pm-discount-salon').value = '';
  document.getElementById('pm-discount-wholesale').value = '';
  document.getElementById('pm-active').value = 'true';
  document.getElementById('pm-error').textContent = '';
  document.getElementById('product-modal').style.display = 'flex';
}

function openEditProduct(id) {
  const p = PRODUCTS.find(x => x.id === id) || window._catalogProducts?.find(x => x.id === id);
  if (!p) return;
  editingProductId = id;
  document.getElementById('product-modal-title').textContent = 'Editar producto';
  document.getElementById('pm-brand').value = p.brand;
  document.getElementById('pm-category').value = p.category || '';
  document.getElementById('pm-code').value = p.color_code || '';
  document.getElementById('pm-barcode').value = p.barcode;
  document.getElementById('pm-name').value = p.name;
  document.getElementById('pm-price-retail').value = p.price_retail || '';
  document.getElementById('pm-price').value = p.price || '';
  document.getElementById('pm-discount-salon').value = p.discount_salon || '';
  document.getElementById('pm-discount-wholesale').value = p.discount_wholesale || '';
  document.getElementById('pm-active').value = p.active ? 'true' : 'false';
  document.getElementById('pm-error').textContent = '';
  document.getElementById('product-modal').style.display = 'flex';
}

function closeProductModal() {
  document.getElementById('product-modal').style.display = 'none';
  editingProductId = null;
}

function calcSalonPrice() {
  const retail = parseFloat(document.getElementById('pm-price-retail').value) || 0;
  const discount = parseFloat(document.getElementById('pm-discount-salon').value) || 0;
  if (retail > 0 && discount > 0) {
    document.getElementById('pm-price').value = (retail * (1 - discount/100)).toFixed(2);
  }
}

async function saveProduct() {
  const brand    = document.getElementById('pm-brand').value.trim();
  const category = document.getElementById('pm-category').value.trim();
  const barcode  = document.getElementById('pm-barcode').value.trim();
  const name     = document.getElementById('pm-name').value.trim();
  const price    = parseFloat(document.getElementById('pm-price').value) || 0;
  const errEl    = document.getElementById('pm-error');

  if (!brand)   { errEl.textContent = 'La marca es requerida'; return; }
  if (!barcode) { errEl.textContent = 'El código de barras es requerido'; return; }
  if (!name)    { errEl.textContent = 'El nombre es requerido'; return; }
  if (!price)   { errEl.textContent = 'El precio salon es requerido'; return; }
  errEl.textContent = '';

  const data = {
    brand, category, barcode,
    color_code: document.getElementById('pm-code').value.trim() || null,
    name, price,
    price_retail: parseFloat(document.getElementById('pm-price-retail').value) || null,
    discount_salon: parseFloat(document.getElementById('pm-discount-salon').value) || null,
    discount_wholesale: (() => {
      const ws = parseFloat(document.getElementById('pm-price-wholesale').value);
      const salon = parseFloat(document.getElementById('pm-price').value);
      if (ws && salon) return parseFloat(((1 - ws / salon) * 100).toFixed(4));
      return parseFloat(document.getElementById('pm-discount-wholesale').value) || null;
    })(),
    active: document.getElementById('pm-active').value === 'true'
  };

  const btn = document.getElementById('pm-save-btn');
  btn.disabled = true;
  btn.textContent = 'Guardando...';

  try {
    if (editingProductId) {
      await supabase(`products?id=eq.${editingProductId}`, { method: 'PATCH', body: JSON.stringify(data) });
    } else {
      await supabase('products', { method: 'POST', headers: { 'Prefer': 'return=representation' }, body: JSON.stringify(data) });
    }
    closeProductModal();
    showToast('✓ Producto guardado');
    PRODUCTS = await dbFetchProducts();
    await loadCatalog();
  } catch(e) {
    errEl.textContent = 'Error al guardar — verifica que el código de barras no esté duplicado';
    console.error(e);
  } finally {
    btn.disabled = false;
    btn.textContent = 'Guardar producto →';
  }
}

async function toggleProduct(id, active) {
  try {
    await supabase(`products?id=eq.${id}`, { method: 'PATCH', body: JSON.stringify({ active }) });
    showToast(active ? '✓ Producto activado' : '✓ Producto desactivado');
    PRODUCTS = await dbFetchProducts();
    await loadCatalog();
  } catch(e) {
    showToast('❌ Error al actualizar');
    console.error(e);
  }
}

async function deleteProduct(id, name) {
  if (!confirm(`¿Eliminar "${name}"? Esta acción no se puede deshacer.`)) return;
  try {
    await supabase(`products?id=eq.${id}`, { method: 'DELETE' });
    showToast('✓ Producto eliminado');
    PRODUCTS = await dbFetchProducts();
    await loadCatalog();
  } catch(e) {
    showToast('❌ Error al eliminar');
    console.error(e);
  }
}




// ── POS ───────────────────────────────────────────────────────
let posCart = [];
let posLevel = 'Salon';
let posSelectedBrand = null;
let posSelectedCategory = null;
let posFilteredProducts = [];
let posClient = null;

function initPOS() {
  posCart = [];
  posClient = null;
  posLevel = 'Salon';
  posMobileCartVisible = false;
  const left = document.querySelector('.pos-left');
  const right = document.querySelector('.pos-right');
  if (left) left.style.display = 'flex';
  if (right) right.style.display = 'flex';
  document.getElementById('pos-level').value = 'Salon';
  document.getElementById('pos-client-search').value = '';
  document.getElementById('pos-client-info').style.display = 'none';
  renderPOSBrands();
  renderPOSCart();
}

function renderPOSBrands() {
  const brands = [...new Set(PRODUCTS.map(p => p.brand))].sort();
  const container = document.getElementById('pos-brand-chips');
  container.innerHTML = brands.map(b => {
    const logo = BRAND_LOGOS[b];
    const img = logo ? `<img src="${logo}" alt="${b}" style="height:28px; max-width:80px; object-fit:contain; display:block; margin:0 auto 2px;">` : '';
    return `<button class="brand-chip ${posSelectedBrand === b ? 'active' : ''}" onclick="selectPOSBrand('${b}')">${img}<span>${b}</span></button>`;
  }).join('');
}

function selectPOSBrand(brand) {
  posSelectedBrand = brand;
  posSelectedCategory = null;
  renderPOSBrands();

  const categories = [...new Set(PRODUCTS.filter(p => p.brand === brand).map(p => p.category))].sort();
  const container = document.getElementById('pos-category-chips');
  container.innerHTML = categories.map(c => `
    <button class="filter-chip ${posSelectedCategory === c ? 'active' : ''}" onclick="selectPOSCategory('${c}')">${c}</button>
  `).join('');
  container.style.display = 'flex';

  if (categories.length === 1) selectPOSCategory(categories[0]);
}

function selectPOSCategory(category) {
  posSelectedCategory = category;
  document.querySelectorAll('#pos-category-chips .filter-chip').forEach(b => b.classList.remove('active'));
  const btn = [...document.querySelectorAll('#pos-category-chips .filter-chip')].find(b => b.textContent === category);
  if (btn) btn.classList.add('active');

  posFilteredProducts = PRODUCTS.filter(p => p.brand === posSelectedBrand && p.category === category);
  renderPOSProducts(posFilteredProducts);
}

function renderPOSProducts(products) {
  const container = document.getElementById('pos-products');
  if (!products.length) {
    container.innerHTML = '<div class="empty-state" style="padding:2rem;">No hay productos</div>';
    return;
  }
  container.innerHTML = products.map(p => {
    const price = getPrice(p);
    const code = p.color_code || '—';
    const inCart = posCart.find(c => c.barcode === p.barcode);
    return `
    <div class="pos-product-card ${inCart ? 'in-cart' : ''}" onclick="posAddProduct('${p.barcode}')">
      ${inCart ? `<div class="pos-in-cart-badge">${inCart.qty}</div>` : ''}
      <div class="pos-product-code">[${code}]</div>
      <div class="pos-product-name">${p.name}</div>
      <div class="pos-product-price">$${price.toFixed(2)}</div>
    </div>
  `}).join('');
}

function posAddProduct(barcode) {
  const product = PRODUCTS.find(p => p.barcode === barcode);
  if (!product) return;
  const existing = posCart.find(c => c.barcode === barcode);
  if (existing) {
    existing.qty++;
    existing.subtotal = getPrice(product) * existing.qty;
  } else {
    const price = getPrice(product);
    posCart.push({ barcode: product.barcode, brand: product.brand, code: product.color_code || '—', name: product.name, price, qty: 1, subtotal: price, is_free: false });
  }
  if (posSelectedCategory) renderPOSProducts(posFilteredProducts);
  renderPOSCart();
}

function posChangeQty(barcode, delta) {
  const item = posCart.find(c => c.barcode === barcode);
  if (!item) return;
  item.qty = Math.max(0, item.qty + delta);
  if (item.qty === 0) {
    posCart = posCart.filter(c => c.barcode !== barcode);
  } else {
    const product = PRODUCTS.find(p => p.barcode === barcode);
    item.price = product ? getPrice(product) : item.price;
    item.subtotal = item.is_free ? 0 : item.price * item.qty;
  }
  if (posSelectedCategory) renderPOSProducts(posFilteredProducts);
  renderPOSCart();
}

function posToggleFree(barcode) {
  const item = posCart.find(c => c.barcode === barcode);
  if (!item) return;
  item.is_free = !item.is_free;
  item.subtotal = item.is_free ? 0 : item.price * item.qty;
  renderPOSCart();
}

function posRemoveItem(barcode) {
  posCart = posCart.filter(c => c.barcode !== barcode);
  if (posSelectedCategory) renderPOSProducts(posFilteredProducts);
  renderPOSCart();
}

// ── POS Mobile view toggle ───────────────────────────────────
let posMobileCartVisible = false;

function togglePOSMobileView() {
  posMobileCartVisible = !posMobileCartVisible;
  const left = document.querySelector('.pos-left');
  const right = document.querySelector('.pos-right');
  if (!left || !right) return;
  if (posMobileCartVisible) {
    left.style.display = 'none';
    right.style.display = 'flex';
  } else {
    left.style.display = 'flex';
    right.style.display = 'none';
  }
}

function updatePOSFAB() {
  const fab = document.getElementById('pos-cart-fab');
  const fabCount = document.getElementById('pos-fab-count');
  const fabTotal = document.getElementById('pos-fab-total');
  if (!fab) return;

  const isMobile = window.innerWidth < 700;
  fab.style.display = isMobile ? 'flex' : 'none';

  const totalQty = posCart.reduce((s, i) => s + i.qty, 0);
  const subtotal = posCart.reduce((s, i) => s + i.subtotal, 0);
  if (fabCount) fabCount.textContent = totalQty;
  if (fabTotal) fabTotal.textContent = '$' + subtotal.toFixed(2);

  // On mobile, show back button in cart view
  const backBtn = document.getElementById('pos-back-btn');
  if (backBtn) backBtn.style.display = isMobile ? 'block' : 'none';
}

function renderPOSCart() {
  const container = document.getElementById('pos-cart-items');
  const countEl = document.getElementById('pos-cart-count');

  if (posCart.length === 0) {
    container.innerHTML = `<div class="pos-empty-cart"><i class="ti ti-shopping-cart" style="font-size:32px;" aria-hidden="true"></i><span>Toca un producto para agregar</span></div>`;
    countEl.textContent = 'vacío';
  } else {
    countEl.textContent = posCart.length + ' producto' + (posCart.length !== 1 ? 's' : '');
    container.innerHTML = posCart.map(item => `
      <div class="pos-cart-item" style="${item.is_free ? 'background:#f0fdf4; border-color:#bbf7d0;' : ''}">
        <div class="pos-cart-info">
          <div class="pos-cart-name">${item.brand} [${item.code}] ${item.name}
            ${item.is_free ? '<span style="margin-left:6px; background:#16a34a; color:#fff; font-size:9px; font-weight:700; padding:1px 6px; border-radius:4px;">FREE</span>' : ''}
          </div>
          <div class="pos-cart-price" style="${item.is_free ? 'color:#16a34a;' : ''}">
            ${item.is_free ? 'GRATIS' : '$' + item.price.toFixed(2) + ' c/u'}
          </div>
        </div>
        <div class="pos-cart-qty">
          <button class="qty-btn" onclick="posChangeQty('${item.barcode}', -1)">−</button>
          <span class="qty-num">${item.qty}</span>
          <button class="qty-btn" onclick="posChangeQty('${item.barcode}', 1)">+</button>
        </div>
        <label style="display:flex; align-items:center; gap:3px; font-size:11px; color:#16a34a; cursor:pointer;">
          <input type="checkbox" ${item.is_free ? 'checked' : ''} onchange="posToggleFree('${item.barcode}')" style="accent-color:#16a34a;"> Gratis
        </label>
        <span class="pos-cart-total" style="${item.is_free ? 'color:#16a34a;' : ''}">$${item.subtotal.toFixed(2)}</span>
        <span class="pos-cart-remove" onclick="posRemoveItem('${item.barcode}')">×</span>
      </div>
    `).join('');
  }
  posRecalc();
  updatePOSFAB();
}

function posRecalc() {
  const subtotal = posCart.reduce((sum, i) => sum + i.subtotal, 0);
  const hasTax = document.getElementById('pos-tax-toggle').checked;
  const taxRate = parseFloat(document.getElementById('pos-tax-rate').value) || 0;
  
  // Discount
  const discountType = document.getElementById('pos-discount-type')?.value || 'pct';
  const discountVal = parseFloat(document.getElementById('pos-discount-val')?.value) || 0;
  const discountAmt = discountType === 'pct' ? subtotal * (discountVal / 100) : Math.min(discountVal, subtotal);
  const subtotalAfterDiscount = subtotal - discountAmt;
  
  const taxAmt = hasTax ? subtotalAfterDiscount * (taxRate / 100) : 0;
  const total = subtotalAfterDiscount + taxAmt;

  document.getElementById('pos-subtotal').textContent = '$' + subtotal.toFixed(2);
  
  const discRow = document.getElementById('pos-discount-row');
  if (discRow) discRow.style.display = discountAmt > 0 ? 'flex' : 'none';
  const discAmt = document.getElementById('pos-discount-amt');
  if (discAmt) discAmt.textContent = '-$' + discountAmt.toFixed(2);
  
  document.getElementById('pos-tax-row').style.display = hasTax ? 'flex' : 'none';
  document.getElementById('pos-tax-label').textContent = `Tax (${taxRate.toFixed(2)}%)`;
  document.getElementById('pos-tax-amt').textContent = '$' + taxAmt.toFixed(2);
  document.getElementById('pos-total').textContent = '$' + total.toFixed(2);

  const btn = document.getElementById('pos-cobrar-btn');
  btn.textContent = `Cobrar $${total.toFixed(2)}`;
  btn.disabled = posCart.length === 0;
}

function setPosLevel(level) {
  posLevel = level;
  currentLevel = level;
  recalcCartPrices();
  if (posSelectedCategory) renderPOSProducts(posFilteredProducts);
  renderPOSCart();
}

function recalcCartPrices() {
  posCart = posCart.map(item => {
    const product = PRODUCTS.find(p => p.barcode === item.barcode);
    if (!product) return item;
    const price = getPrice(product);
    return { ...item, price, subtotal: price * item.qty };
  });
}

function posSearch(query) {
  if (!query || query.length < 2) {
    if (posSelectedCategory) renderPOSProducts(posFilteredProducts);
    return;
  }
  const q = query.toLowerCase();
  const results = PRODUCTS.filter(p =>
    p.name.toLowerCase().includes(q) ||
    (p.color_code && p.color_code.toLowerCase().includes(q)) ||
    p.brand.toLowerCase().includes(q)
  );
  renderPOSProducts(results);
}

function posScanBarcode(e) {
  if (e.key !== 'Enter') return;
  const barcode = document.getElementById('pos-search').value.trim();
  document.getElementById('pos-search').value = '';
  const product = PRODUCTS.find(p => p.barcode === barcode);
  if (product) {
    posAddProduct(barcode);
    showToast(`✓ ${product.name} agregado`);
  } else {
    showToast('⚠️ Producto no encontrado');
  }
}

function posSearchClient(query) {
  const box = document.getElementById('pos-client-suggestions');
  if (!query || query.length < 2) { box.style.display = 'none'; return; }
  const q = query.toLowerCase();
  const matches = allCustomers.filter(c =>
    c.name.toLowerCase().includes(q) || c.business.toLowerCase().includes(q) || c.phone.includes(q)
  ).slice(0, 5);
  if (!matches.length) { box.style.display = 'none'; return; }
  box.innerHTML = matches.map(c => `
    <div class="suggestion-item" onclick="selectPOSClient(${c.id})">
      <div class="suggestion-name">${c.name}</div>
      <div class="suggestion-detail">${c.business} · ${c.phone}</div>
    </div>
  `).join('');
  box.style.display = 'block';
}

function selectPOSClient(id) {
  posClient = allCustomers.find(c => c.id === id);
  if (!posClient) return;
  document.getElementById('pos-client-search').value = `${posClient.name} — ${posClient.business}`;
  document.getElementById('pos-client-suggestions').style.display = 'none';
  document.getElementById('pos-client-info').style.display = 'block';
  document.getElementById('pos-client-info').textContent = `${posClient.phone} · ${posClient.address || ''}`;
  // Set level from client profile
  posLevel = posClient.level || 'Salon';
  document.getElementById('pos-level').value = posLevel;
  currentLevel = posLevel;
  recalcCartPrices();
  if (posSelectedCategory) renderPOSProducts(posFilteredProducts);
  renderPOSCart();
}

function posCobrar() {
  if (posCart.length === 0) return;
  const subtotal = posCart.reduce((sum, i) => sum + i.subtotal, 0);
  const hasTax = document.getElementById('pos-tax-toggle').checked;
  const taxRate = parseFloat(document.getElementById('pos-tax-rate').value) || 0;
  const taxAmt = hasTax ? subtotal * (taxRate / 100) : 0;
  const total = subtotal + taxAmt;

  const subtotal2 = posCart.reduce((sum, i) => sum + i.subtotal, 0);
  const discType = document.getElementById('pos-discount-type')?.value || 'pct';
  const discVal = parseFloat(document.getElementById('pos-discount-val')?.value) || 0;
  const discAmt2 = discType === 'pct' ? subtotal2 * (discVal / 100) : Math.min(discVal, subtotal2);
  const hasTax2 = document.getElementById('pos-tax-toggle').checked;
  const taxRate2 = parseFloat(document.getElementById('pos-tax-rate').value) || 0;
  const taxAmt3 = hasTax2 ? (subtotal2 - discAmt2) * (taxRate2 / 100) : 0;
  const total3 = subtotal2 - discAmt2 + taxAmt3;

  const clientName = posClient ? posClient.name : 'Cliente general';
  document.getElementById('cobrar-summary').innerHTML = `
    <strong>${clientName}</strong><br>
    ${posCart.length} producto${posCart.length !== 1 ? 's' : ''}${discAmt2 > 0 ? ` · Descuento: -$${discAmt2.toFixed(2)}` : ''} · Total: <strong>$${total3.toFixed(2)}</strong>
  `;

  document.getElementById('cobrar-modal').style.display = 'flex';
}

function closeCobrarModal() {
  document.getElementById('cobrar-modal').style.display = 'none';
}

async function confirmCobrar() {
  const payment = document.getElementById('cobrar-payment').value;
  const subtotal = posCart.reduce((sum, i) => sum + i.subtotal, 0);
  const hasTax = document.getElementById('pos-tax-toggle').checked;
  const taxRate = parseFloat(document.getElementById('pos-tax-rate').value) || 0;
  const taxAmt = hasTax ? subtotal * (taxRate / 100) : 0;
  const total = subtotal + taxAmt;

  const discountType = document.getElementById('pos-discount-type')?.value || 'pct';
  const discountVal = parseFloat(document.getElementById('pos-discount-val')?.value) || 0;
  const discountAmt = discountType === 'pct' ? subtotal * (discountVal / 100) : Math.min(discountVal, subtotal);
  const subtotalAfterDiscount = subtotal - discountAmt;
  const taxAmt2 = hasTax ? subtotalAfterDiscount * (taxRate / 100) : 0;
  const total2 = subtotalAfterDiscount + taxAmt2;

  const btn = document.getElementById('cobrar-confirm-btn');
  btn.disabled = true;
  btn.textContent = 'Procesando...';

  try {
    const discountNote = discountAmt > 0 ? ` · Descuento: -$${discountAmt.toFixed(2)}` : '';
    const posSellerInput = document.getElementById('pos-seller-name');
    const posSeller = (posSellerInput?.value.trim()) || currentUser?.name || 'Caja';
    const orderData = {
      seller: posSeller,
      client: posClient ? posClient.name : 'Cliente general',
      business: posClient ? posClient.business : 'Venta en bodega',
      phone: posClient ? posClient.phone : '—',
      permit: posClient ? (posClient.permit || '') : '',
      address: posClient ? (posClient.address || '') : 'Bodega',
      email: posClient ? (posClient.email || '') : '',
      notes: `Venta en caja · Pago: ${payment}${discountNote}`,
      payment_method: payment,
      lines: posCart,
      subtotal,
      shipping: null,
      tax_rate: hasTax ? taxRate : null,
      tax_amount: hasTax ? taxAmt2 : null,
      total: total2,
      status: 'Entregada'
    };

    const inserted = await dbInsertOrder(orderData);

    // Deduct inventory
    for (const item of posCart) {
      try {
        const prod = PRODUCTS.find(p => p.barcode === item.barcode);
        if (prod && prod.id) {
          const current = await supabase(`products?id=eq.${prod.id}&select=id,stock`);
          if (current && current[0]) {
            const newStock = Math.max(0, (current[0].stock || 0) - item.qty);
            await supabase(`products?id=eq.${prod.id}`, { method: 'PATCH', body: JSON.stringify({ stock: newStock }) });
            await supabase('inventory_movements', {
              method: 'POST',
              headers: { 'Prefer': 'return=representation' },
              body: JSON.stringify({ product_id: prod.id, type: 'out', quantity: item.qty, order_id: inserted[0]?.id, notes: `Venta en caja` })
            });
          }
        }
      } catch(e) { console.error('Stock error:', e); }
    }

    // Update customer if selected
    if (posClient) {
      await dbUpsertCustomer({ client: posClient.name, business: posClient.business, phone: posClient.phone, address: posClient.address, permit: posClient.permit, email: posClient.email });
    }

    closeCobrarModal();
    // Print receipt directly with full order data
    if (inserted && inserted[0]) {
      const orderForPrint = { ...orderData, id: inserted[0].id, created_at: new Date().toISOString(), total: total2 };
      if (!window._orders) window._orders = [];
      window._orders.unshift(orderForPrint);
      printOrder(inserted[0].id);
    }

    showToast(`✓ Venta registrada — $${total2.toFixed(2)}`);

    // Reset POS
    posCart = [];
    posClient = null;
    document.getElementById('pos-client-search').value = '';
    document.getElementById('pos-client-info').style.display = 'none';
    if (posSelectedCategory) renderPOSProducts(posFilteredProducts);
    renderPOSCart();

  } catch(e) {
    showToast('❌ Error al procesar venta');
    console.error(e);
  } finally {
    btn.disabled = false;
    btn.textContent = 'Confirmar y cobrar →';
  }
}

// ── Picking ───────────────────────────────────────────────────
let pickingOrder = null;

async function openPicking(id) {
  const order = allOrders.find(o => o.id === id) || window._orders?.find(o => o.id === id);
  if (!order) {
    try {
      const res = await supabase(`orders?id=eq.${id}&select=*`);
      pickingOrder = res && res[0];
    } catch(e) { showToast('❌ Error cargando orden'); return; }
  } else {
    pickingOrder = order;
  }
  if (!pickingOrder) return;

  // Init picking state from saved or fresh
  const savedPicking = pickingOrder.picking || {};

  // Restore adjusted qtys from saved picking into memory
  pickingOrder._adjustedQtys = {};
  Object.keys(savedPicking).forEach(key => {
    if (key.startsWith('qty_')) {
      const idx = parseInt(key.replace('qty_', ''));
      pickingOrder._adjustedQtys[idx] = savedPicking[key];
    }
  });
  
  document.getElementById('picking-order-title').textContent = `Picking — ${pickingOrder.client}`;
  document.getElementById('picking-business').textContent = pickingOrder.business;
  
  const linesHTML = pickingOrder.lines.map((l, idx) => {
    const checked = savedPicking[idx] || false;
    const adjustedQty = savedPicking[`qty_${idx}`] !== undefined ? savedPicking[`qty_${idx}`] : l.qty;
    const isAdjusted = adjustedQty < l.qty;
    return `
    <div class="picking-item ${checked ? 'picked' : ''}" id="pick-item-${idx}" style="cursor:pointer;">
      <div class="picking-checkbox ${checked ? 'checked' : ''}" onclick="togglePick(${idx})">
        ${checked ? '✓' : ''}
      </div>
      <div class="picking-info" onclick="togglePickExpand(${idx})" style="flex:1;">
        <div class="picking-product">${l.brand} [${l.code}] ${l.name}</div>
        <div class="picking-qty">Quantity: <strong id="pick-qty-label-${idx}">${adjustedQty}</strong>${isAdjusted ? ` <span style="color:#d97706; font-size:10px;">(ordered: ${l.qty})</span>` : ''} &nbsp;·&nbsp; <span style="font-family:monospace; font-size:11px; color:var(--text-faint);">${l.barcode}</span></div>
      </div>
    </div>
    <div id="pick-expand-${idx}" style="display:none; padding:8px 12px 12px 52px; background:#fffbeb; border-bottom:1px solid var(--border);">
      <div style="font-size:12px; color:#666; margin-bottom:6px;">Adjust dispatched quantity:</div>
      <div style="display:flex; align-items:center; gap:8px;">
        <input type="number" id="pick-qty-input-${idx}" value="${adjustedQty}" min="0" max="${l.qty}" style="width:70px; padding:4px 8px; border:1px solid var(--border); border-radius:6px; font-size:14px; font-weight:600;" oninput="updatePickQty(${idx}, ${l.qty})">
        <span style="font-size:12px; color:#888;">of ${l.qty} ordered</span>
        <button onclick="applyPickQty(${idx}, ${l.qty})" style="padding:4px 12px; background:var(--gold); color:#fff; border:none; border-radius:6px; font-size:12px; cursor:pointer; font-weight:600;">Apply</button>
      </div>
    </div>
  `}).join('');

  document.getElementById('picking-lines').innerHTML = linesHTML;
  updatePickingProgress();
  document.getElementById('picking-modal').style.display = 'flex';
  // Focus scan input
  setTimeout(() => document.getElementById('picking-scan-input').focus(), 200);
}

function handlePickingScan(e) {
  if (e.key !== 'Enter') return;
  const input = document.getElementById('picking-scan-input');
  const barcode = input.value.trim();
  input.value = '';
  if (!barcode || !pickingOrder) return;

  // Find matching product in order
  const idx = pickingOrder.lines.findIndex(l => l.barcode === barcode);
  if (idx === -1) {
    showPickingScanFeedback('❌ Producto no encontrado en esta orden', 'error');
    return;
  }

  const item = document.getElementById(`pick-item-${idx}`);
  if (item.classList.contains('picked')) {
    showPickingScanFeedback('⚠️ Este producto ya fue escaneado', 'warning');
    return;
  }

  // Mark as picked
  item.classList.add('picked');
  const checkbox = item.querySelector('.picking-checkbox');
  checkbox.classList.add('checked');
  checkbox.textContent = '✓';
  item.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  showPickingScanFeedback(`✓ ${pickingOrder.lines[idx].name}`, 'success');
  updatePickingProgress();
}

function showPickingScanFeedback(msg, type) {
  const el = document.getElementById('picking-scan-feedback');
  const colors = { success: '#16a34a', error: '#dc2626', warning: '#d97706' };
  el.textContent = msg;
  el.style.color = colors[type] || '#16a34a';
  el.style.opacity = '1';
  setTimeout(() => { el.style.opacity = '0'; }, 2000);
}

function togglePick(idx) {
  const item = document.getElementById(`pick-item-${idx}`);
  if (!item) return;
  const checkbox = item.querySelector('.picking-checkbox');
  const isPicked = item.classList.contains('picked');
  if (isPicked) {
    item.classList.remove('picked');
    if (checkbox) { checkbox.classList.remove('checked'); checkbox.textContent = ''; }
  } else {
    item.classList.add('picked');
    if (checkbox) { checkbox.classList.add('checked'); checkbox.textContent = '✓'; }
  }
  updatePickingProgress();
}

function togglePickExpand(idx) {
  const expand = document.getElementById(`pick-expand-${idx}`);
  if (!expand) return;
  const isOpen = expand.style.display !== 'none';
  // Close all others
  pickingOrder.lines.forEach((_, i) => {
    const el = document.getElementById(`pick-expand-${i}`);
    if (el) el.style.display = 'none';
  });
  if (!isOpen) {
    expand.style.display = 'block';
    const input = document.getElementById(`pick-qty-input-${idx}`);
    if (input) setTimeout(() => input.focus(), 100);
  }
}

function updatePickQty(idx, maxQty) {
  const input = document.getElementById(`pick-qty-input-${idx}`);
  if (!input) return;
  let val = parseInt(input.value) || 0;
  if (val > maxQty) { val = maxQty; input.value = maxQty; }
  if (val < 0) { val = 0; input.value = 0; }
}

function applyPickQty(idx, originalQty) {
  const input = document.getElementById(`pick-qty-input-${idx}`);
  const label = document.getElementById(`pick-qty-label-${idx}`);
  if (!input || !label) return;
  const qty = parseInt(input.value) || 0;

  // Update label
  label.textContent = qty;

  // Show/hide adjusted warning
  const qtyDiv = label.parentElement;
  const existing = qtyDiv.querySelector('.adjusted-warning');
  if (existing) existing.remove();
  if (qty < originalQty) {
    const warning = document.createElement('span');
    warning.className = 'adjusted-warning';
    warning.style.cssText = 'color:#d97706; font-size:10px; margin-left:4px;';
    warning.textContent = `(ordered: ${originalQty})`;
    label.after(warning);
  }

  // Save adjusted qty to picking state
  if (!pickingOrder._adjustedQtys) pickingOrder._adjustedQtys = {};
  pickingOrder._adjustedQtys[idx] = qty;

  // Close expand
  const expand = document.getElementById(`pick-expand-${idx}`);
  if (expand) expand.style.display = 'none';

  showToast(`✓ Quantity updated to ${qty}`);
}

function updatePickingProgress() {
  const total = pickingOrder.lines.length;
  const picked = document.querySelectorAll('.picking-item.picked').length;
  document.getElementById('picking-progress').textContent = `${picked} / ${total} productos`;
  document.getElementById('picking-confirm-btn').disabled = picked < total;
  document.getElementById('picking-confirm-btn').style.opacity = picked < total ? '0.5' : '1';
}

async function savePicking() {
  if (!pickingOrder) return;
  const picking = {};

  pickingOrder.lines.forEach((l, idx) => {
    const el = document.getElementById(`pick-item-${idx}`);
    picking[String(idx)] = el ? el.classList.contains('picked') : false;
  });

  // Save adjusted qtys
  const adjustedQtys = pickingOrder._adjustedQtys || {};
  Object.keys(adjustedQtys).forEach(idx => {
    picking[`qty_${idx}`] = adjustedQtys[idx];
  });

  // Update local reference so reopening the modal shows saved state
  pickingOrder.picking = picking;

  try {
    await supabase(`orders?id=eq.${pickingOrder.id}`, {
      method: 'PATCH',
      body: JSON.stringify({ picking })
    });
    showToast('💾 Progreso guardado');
  } catch(e) {
    console.error('savePicking error:', e);
    showToast('❌ Error al guardar');
  }
}

async function confirmPicking() {
  if (!pickingOrder) return;
  if (!confirm('¿Confirmar picking completo? Esto descontará el inventario y marcará la orden como Lista.')) return;

  const btn = document.getElementById('picking-confirm-btn');
  btn.disabled = true;
  btn.textContent = 'Procesando...';

  try {
    // Deduct stock for each product using adjusted qty if applicable
    const adjustedQtys = pickingOrder._adjustedQtys || {};
    const updatedLines = pickingOrder.lines.map((line, idx) => {
      const dispatchedQty = adjustedQtys[idx] !== undefined ? adjustedQtys[idx] : line.qty;
      return { ...line, dispatched_qty: dispatchedQty };
    });

    for (let idx = 0; idx < updatedLines.length; idx++) {
      const line = updatedLines[idx];
      const dispatchedQty = line.dispatched_qty;
      try {
        const prod = PRODUCTS.find(p => p.barcode === line.barcode);
        if (prod && prod.id) {
          const current = await supabase(`products?id=eq.${prod.id}&select=id,stock`);
          if (current && current[0]) {
            const newStock = Math.max(0, (current[0].stock || 0) - dispatchedQty);
            await supabase(`products?id=eq.${prod.id}`, { method: 'PATCH', body: JSON.stringify({ stock: newStock }) });
            await supabase('inventory_movements', {
              method: 'POST',
              headers: { 'Prefer': 'return=representation' },
              body: JSON.stringify({ product_id: prod.id, type: 'out', quantity: dispatchedQty, order_id: pickingOrder.id, notes: `Picking order #${pickingOrder.id}${dispatchedQty < line.qty ? ` (adjusted: ${dispatchedQty} of ${line.qty} ordered)` : ''}` })
            });
          }
        }
      } catch(e) { console.error('Stock error:', e); }
    }

    // Mark picking complete and update status, save adjusted lines
    const picking = {};
    pickingOrder.lines.forEach((l, idx) => { picking[idx] = true; });
    // Save adjusted qty info per line index
    Object.keys(adjustedQtys).forEach(idx => { picking[`qty_${idx}`] = adjustedQtys[idx]; });

    await supabase(`orders?id=eq.${pickingOrder.id}`, {
      method: 'PATCH',
      body: JSON.stringify({ status: 'Lista', picking, lines: updatedLines })
    });

    closePicking();
    showToast('✓ Picking completo — orden marcada como Lista');
    await loadOrders();
  } catch(e) {
    showToast('❌ Error al confirmar picking');
    console.error(e);
  } finally {
    btn.disabled = false;
    btn.textContent = '✅ Confirmar picking completo';
  }
}


