function renderCustomers(customers) {
  const list = document.getElementById('customers-list');
  const countLabel = document.getElementById('customer-count-label');
  countLabel.textContent = customers.length + ' cliente' + (customers.length !== 1 ? 's' : '');

  if (customers.length === 0) {
    list.innerHTML = `<div class="empty-state"><div class="empty-icon">👥</div>No hay clientes todavía</div>`;
    return;
  }

  list.innerHTML = customers.map(c => {
    const lastOrder = c.last_order_at ? new Date(c.last_order_at).toLocaleDateString('es-MX') : '—';
    const phone = c.phone.replace(/[^0-9]/g, '');
    const waLink = `https://wa.me/1${phone}`;
    const emailLink = c.email ? `mailto:${c.email}` : null;
    const levelColors = { Retail: 'badge-nueva', Salon: 'badge-lista', Wholesale: 'badge-proceso' };
    const levelColor = levelColors[c.level] || 'badge-nueva';
    const levelOptions = LEVELS.map(l => `<option value="${l}" ${c.level === l ? 'selected' : ''}>${l}</option>`).join('');

    // Preferred customer logic
    const isPreferred = c.is_preferred;
    const prefUntil = c.preferred_until ? new Date(c.preferred_until) : null;
    const today = new Date(); today.setHours(0,0,0,0);
    const prefActive = isPreferred && prefUntil && prefUntil >= today;
    const prefExpired = isPreferred && prefUntil && prefUntil < today;
    const prefUntilStr = prefUntil ? prefUntil.toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' }) : '';

    return `
    <div class="order-card" style="${isPreferred ? 'border-left: 3px solid var(--gold);' : ''}">
      <div class="order-header">
        <div>
          <div class="order-name">${c.name} ${isPreferred ? '<span style="font-size:12px; color:var(--gold);">⭐ Preferred</span>' : ''}</div>
          <div class="order-business">${c.business}</div>
        </div>
        <div style="display:flex; gap:8px; align-items:center; flex-wrap:wrap;">
          <select class="status-select ${levelColor}" onchange="updateCustomerLevel(${c.id}, this.value)">${levelOptions}</select>
        </div>
      </div>
      ${prefActive ? `
      <div style="background:var(--gold-pale); border:1px solid var(--gold-border); border-radius:6px; padding:8px 12px; margin-bottom:6px; font-size:12px;">
        💰 Special discount: <strong>$${parseFloat(c.preferred_discount).toFixed(2)}</strong> per order
        · Valid until: <strong>${prefUntilStr}</strong>
        ${c.preferred_note ? `<div style="color:var(--text-muted); margin-top:2px;">📝 ${c.preferred_note}</div>` : ''}
      </div>` : ''}
      ${prefExpired ? `
      <div style="background:#fff7ed; border:1px solid #fed7aa; border-radius:6px; padding:8px 12px; margin-bottom:6px; font-size:12px; color:#92400e;">
        ⏰ Special pricing expired on ${prefUntilStr} — still a Preferred Customer
      </div>` : ''}
      <div class="order-meta">
        📞 ${c.phone}
        ${c.email ? ` · ✉️ ${c.email}` : ''}
      </div>
      <div class="order-meta">
        📍 ${c.address || '—'}
        ${c.permit ? ` · Permit: ${c.permit}` : ''}
      </div>
      <div class="order-meta">
        🛒 ${c.order_count} orden${c.order_count !== 1 ? 'es' : ''} · Última: ${lastOrder}
      </div>
      <div class="order-meta" style="margin-top:8px; display:flex; gap:8px; flex-wrap:wrap;">
        <a href="${waLink}" target="_blank" class="contact-btn wa-btn">💬 WhatsApp</a>
        ${emailLink ? `<a href="${emailLink}" class="contact-btn email-btn">✉️ Email</a>` : ''}
        <button onclick="openEditCustomer(${c.id})" class="contact-btn" style="border:1px solid var(--border); color:var(--text-muted); background:none; cursor:pointer; font-family:inherit;">✏️ Editar</button>
        <button onclick="openHistoryModal(${c.id})" class="contact-btn" style="border:1px solid var(--border); color:var(--text-muted); background:none; cursor:pointer; font-family:inherit;">📋 Historial</button>
      </div>
    </div>
  `}).join('');
}

async function updateCustomerLevel(id, level) {
  try {
    await supabase(`customers?id=eq.${id}`, {
      method: 'PATCH',
      body: JSON.stringify({ level })
    });
    // Update in local cache
    const c = allCustomers.find(x => x.id === id);
    if (c) c.level = level;
    showToast(`✓ Nivel actualizado a ${level}`);
    await loadCustomers();
  } catch(e) {
    showToast('❌ Error al actualizar nivel');
    console.error(e);
  }
}

// ── Tab switching ────────────────────────────────────────────
function showTab(name) {
  // All tabs require login
  if (!currentRole) { showLoginModal(); return; }
  // Role-based access
  if ((name === 'admin' || name === 'customers' || name === 'catalog' || name === 'inventory' || name === 'sellers') && !isAdmin) { return; }
  if (name === 'miprogreso' && currentRole !== 'seller') { return; }
  if (name === 'delivery' && !isDelivery && !isAdmin) { return; }
  if (name === 'pos' && currentRole === 'delivery') { return; }

  document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
  document.getElementById('tab-' + name).classList.add('active');
  document.getElementById('tab-' + name + '-btn').classList.add('active');

  // Always show logout when logged in
  document.getElementById('logout-btn').style.display = 'inline-block';

  // Tab-specific init
  if (name === 'admin') loadOrders();
  if (name === 'customers') loadCustomers();
  if (name === 'catalog') loadCatalog();
  if (name === 'inventory') loadInventory();
  if (name === 'pos') initPOS();
  if (name === 'sellers') initSellersTab();
  if (name === 'miprogreso') initMiProgreso();
  if (name === 'suppliers') initSuppliersTab();
  if (name === 'delivery') loadDeliveryOrders();
  if (name === 'delivery' && isAdmin) document.getElementById('tab-delivery-btn').style.display = '';
}

// ── Init — load products from Supabase then boot the form ────
async function init() {
  const productLines = document.getElementById('product-lines');
  productLines.innerHTML = `<div style="font-size:13px; color:var(--text-muted); padding:8px 0;">Cargando productos...</div>`;

  try {
    PRODUCTS = await dbFetchProducts();
  } catch(e) {
    productLines.innerHTML = `<div style="font-size:13px; color:var(--danger);">Error cargando productos</div>`;
    console.error(e);
    return;
  }

  productLines.innerHTML = '';
  initSteppedSelector();
  onPermitChange();
  await loadCustomersList();
}

init();

// ── Scanner (ZXing UMD — iPhone, Android, desktop) ──────────
let scannerActive = false;
let codeReader = null;
let scannedBarcode = null;

async function openScanner() {
  document.getElementById('scanner-modal').style.display = 'flex';
  document.getElementById('scanner-status').textContent = 'Iniciando cámara...';
  scannerActive = true;

  try {
    codeReader = new ZXing.BrowserMultiFormatReader();
    const devices = await ZXing.BrowserCodeReader.listVideoInputDevices();
    const backCamera = devices.find(d => d.label.toLowerCase().includes('back') || d.label.toLowerCase().includes('rear'));
    const deviceId = backCamera ? backCamera.deviceId : (devices[devices.length - 1]?.deviceId);
    document.getElementById('scanner-status').textContent = 'Apunta al código de barras...';
    codeReader.decodeFromVideoDevice(deviceId, 'scanner-video', (result, err) => {
      if (result && scannerActive) {
        scannerActive = false;
        const code = result.getText();
        closeScanner();
        handleScannedCode(code);
      }
    });
  } catch(e) {
    document.getElementById('scanner-status').textContent = '❌ No se pudo acceder a la cámara. Verifica los permisos.';
    console.error(e);
  }
}

function closeScanner() {
  scannerActive = false;
  if (codeReader) {
    try { codeReader.reset(); } catch(e) {}
    codeReader = null;
  }
  document.getElementById('scanner-modal').style.display = 'none';
}

function handleScannedCode(barcode) {
  const product = PRODUCTS.find(p => p.barcode === barcode);
  if (!product) {
    showToast('⚠️ Producto no encontrado: ' + barcode);
    return;
  }
  scannedBarcode = barcode;
  const code = product.color_code ? `[${product.color_code}] ` : '';
  document.getElementById('qty-modal-title').textContent = 'Producto encontrado';
  document.getElementById('qty-modal-product').textContent = `${product.brand} ${code}${product.name} — $${parseFloat(product.price).toFixed(2)}`;
  document.getElementById('qty-modal-input').value = 1;
  document.getElementById('qty-modal').style.display = 'flex';
  setTimeout(() => document.getElementById('qty-modal-input').select(), 150);
}

function confirmScanQty() {
  const qty = parseInt(document.getElementById('qty-modal-input').value) || 1;
  const barcode = scannedBarcode;
  closeQtyModal();
  if (barcode) {
    addProductLine(barcode, qty);
    showToast('✓ Producto agregado');
  }
}

function closeQtyModal() {
  document.getElementById('qty-modal').style.display = 'none';
  scannedBarcode = null;
}

document.addEventListener('keydown', e => {
  if (document.getElementById('qty-modal').style.display === 'flex' && e.key === 'Enter') confirmScanQty();
});

// ── Edit order ───────────────────────────────────────────────
let editingOrderId = null;
let editLineCount = 0;

async function openEditModal(id) {
  const order = window._orders ? window._orders.find(o => o.id === id) : null;
  if (!order) return;
  editingOrderId = id;
  editLineCount = 0;

  document.getElementById('edit-client-name').value = order.client;
  document.getElementById('edit-business-name').value = order.business;
  document.getElementById('edit-phone').value = order.phone;
  document.getElementById('edit-permit').value = order.permit || '';
  document.getElementById('edit-address').value = order.address;
  document.getElementById('edit-email').value = order.email || '';
  document.getElementById('edit-notes').value = order.notes || '';
  document.getElementById('edit-shipping-toggle').checked = order.shipping !== null && order.shipping !== undefined;
  document.getElementById('edit-tax-toggle').checked = !!order.tax_rate;
  document.getElementById('edit-tax-rate').value = order.tax_rate || 10.25;

  // Get level from order first, then match customer by phone or name
  let editLevel = order.level || null;
  if (!editLevel) {
    const normalizePhone = p => (p || '').replace(/[^0-9]/g, '');
    const orderPhone = normalizePhone(order.phone);
    const orderName  = (order.client || '').trim().toLowerCase();

    // Try cache first
    let editCustomer = (allCustomers || []).find(c =>
      (orderPhone && normalizePhone(c.phone) === orderPhone) ||
      (orderName  && (c.name || '').trim().toLowerCase() === orderName)
    );

    // Fallback: fetch from DB and match by phone digits or name
    if (!editCustomer) {
      try {
        const res = await supabase(`customers?select=name,phone,level`);
        editCustomer = (res || []).find(c =>
          (orderPhone && normalizePhone(c.phone) === orderPhone) ||
          (orderName  && (c.name || '').trim().toLowerCase() === orderName)
        );
      } catch(e) {}
    }

    editLevel = editCustomer?.level || 'Salon';
  }
  window._editOrderLevel = editLevel;
  // Set level selector and badge
  const editLvlSel = document.getElementById('edit-level-select');
  if (editLvlSel) editLvlSel.value = editLevel;
  setEditLevel(editLevel);

  const lines = document.getElementById('edit-product-lines');
  lines.innerHTML = '';
  order.lines.forEach(l => addEditLine(l.barcode, l.qty, editLevel));

  onEditPermitChange();
  recalcEditTotal();
  document.getElementById('edit-modal').style.display = 'flex';
}

function closeEditModal() {
  document.getElementById('edit-modal').style.display = 'none';
  editingOrderId = null;
}

function setEditLevel(level) {
  window._editOrderLevel = level;
  const badge = document.getElementById('edit-level-badge');
  const colors = { Retail: 'badge-nueva', Salon: 'badge-lista', Wholesale: 'badge-proceso' };
  if (badge) {
    badge.textContent = level;
    badge.className = 'level-badge ' + (colors[level] || '');
  }
  // Rebuild all product lines with new pricing
  const lines = document.getElementById('edit-product-lines');
  if (lines) {
    const rows = lines.querySelectorAll('.product-row');
    rows.forEach(row => {
      const sel = row.querySelector('select');
      if (sel) {
        const currentBarcode = sel.value;
        sel.innerHTML = buildOptions(currentBarcode, level);
      }
    });
  }
  recalcEditTotal();
}

function addEditLine(barcode = '', qty = 1, level = null) {
  const lvl = level || window._editOrderLevel || currentLevel || 'Salon';
  editLineCount++;
  const id = editLineCount;
  const container = document.getElementById('edit-product-lines');
  const div = document.createElement('div');
  div.className = 'product-row';
  div.id = 'edit-line-' + id;
  div.innerHTML = `
    <select id="edit-sel-${id}" onchange="recalcEditTotal()">${buildOptions(barcode, lvl)}</select>
    <input type="number" id="edit-qty-${id}" value="${qty}" min="1" max="999" step="1" oninput="recalcEditTotal()">
    <button class="remove-btn" onclick="removeEditLine(${id})" aria-label="Eliminar">×</button>
  `;
  container.appendChild(div);
  recalcEditTotal();
}

function removeEditLine(id) {
  const el = document.getElementById('edit-line-' + id);
  if (el) el.remove();
  recalcEditTotal();
}

function onEditPermitChange() {
  const permit = document.getElementById('edit-permit').value.trim();
  const taxRow = document.getElementById('edit-tax-toggle-row');
  const taxToggle = document.getElementById('edit-tax-toggle');
  if (permit.length > 0) {
    taxToggle.checked = false;
    taxRow.style.opacity = '0.4';
    taxRow.style.pointerEvents = 'none';
  } else {
    taxRow.style.opacity = '1';
    taxRow.style.pointerEvents = 'auto';
  }
  recalcEditTotal();
}

function recalcEditTotal() {
  let subtotal = 0;
  document.querySelectorAll('#edit-product-lines .product-row').forEach(row => {
    const sel = row.querySelector('select');
    const qty = row.querySelector('input[type=number]');
    if (sel && qty) {
      const price = parseFloat(sel.selectedOptions[0]?.dataset?.price || 0);
      subtotal += price * (parseInt(qty.value) || 0);
    }
  });
  const hasShipping = document.getElementById('edit-shipping-toggle').checked;
  const hasTax = document.getElementById('edit-tax-toggle').checked;
  const taxRate = parseFloat(document.getElementById('edit-tax-rate').value) || 0;
  const shippingAmt = hasShipping ? SHIPPING : 0;
  const taxAmt = hasTax ? subtotal * (taxRate / 100) : 0;
  const total = subtotal + shippingAmt + taxAmt;

  document.getElementById('edit-sum-products').textContent = '$' + subtotal.toFixed(2);
  document.getElementById('edit-sum-shipping-row').style.display = hasShipping ? 'flex' : 'none';
  document.getElementById('edit-sum-tax-row').style.display = hasTax ? 'flex' : 'none';
  document.getElementById('edit-sum-tax-label').textContent = 'Tax (' + taxRate.toFixed(2) + '%)';
  document.getElementById('edit-sum-tax-amount').textContent = '$' + taxAmt.toFixed(2);
  document.getElementById('edit-order-total').textContent = '$' + total.toFixed(2);
  document.getElementById('edit-tax-rate-row').style.display = hasTax ? 'block' : 'none';
}

async function saveEditOrder() {
  if (!editingOrderId) return;

  const client   = document.getElementById('edit-client-name').value.trim();
  const business = document.getElementById('edit-business-name').value.trim();
  const phone    = document.getElementById('edit-phone').value.trim();
  const permit   = document.getElementById('edit-permit').value.trim();
  const address  = document.getElementById('edit-address').value.trim();
  const email    = document.getElementById('edit-email').value.trim();
  const notes    = document.getElementById('edit-notes').value.trim();

  if (!client)   { showToast('⚠️ Nombre del cliente requerido'); return; }
  if (!business) { showToast('⚠️ Nombre del negocio requerido'); return; }
  if (!phone)    { showToast('⚠️ Teléfono requerido'); return; }
  if (!address)  { showToast('⚠️ Dirección requerida'); return; }

  const lines = [];
  let subtotal = 0;
  document.querySelectorAll('#edit-product-lines .product-row').forEach(row => {
    const sel = row.querySelector('select');
    const qty = row.querySelector('input[type=number]');
    if (sel && qty) {
      const product = PRODUCTS.find(p => p.barcode === sel.value);
      const q = parseInt(qty.value) || 0;
      if (product && q > 0) {
        const lvl = window._editOrderLevel || 'Salon';
        const retail = parseFloat(product.price_retail) || parseFloat(product.price);
        const salon = parseFloat(product.price);
        const wDisc = parseFloat(product.discount_wholesale) || 0;
        const wholesale = Math.round(salon * (1 - wDisc / 100) * 100) / 100;
        const linePrice = lvl === 'Retail' ? retail : lvl === 'Wholesale' ? wholesale : salon;
        const lineSubtotal = linePrice * q;
        lines.push({ barcode: product.barcode, brand: product.brand, code: product.color_code || '—', name: product.name, price: linePrice, qty: q, subtotal: lineSubtotal });
        subtotal += lineSubtotal;
      }
    }
  });

  if (lines.length === 0) { showToast('⚠️ Agrega al menos un producto'); return; }

  const hasShipping = document.getElementById('edit-shipping-toggle').checked;
  const hasTax      = document.getElementById('edit-tax-toggle').checked;
  const taxRate     = parseFloat(document.getElementById('edit-tax-rate').value) || 0;
  const shippingAmt = hasShipping ? SHIPPING : 0;
  const taxAmt      = hasTax ? subtotal * (taxRate / 100) : 0;
  const total       = subtotal + shippingAmt + taxAmt;

  const btn = document.getElementById('edit-save-btn');
  btn.disabled = true;
  btn.textContent = 'Guardando...';

  try {
    await supabase(`orders?id=eq.${editingOrderId}`, {
      method: 'PATCH',
      body: JSON.stringify({ client, business, phone, permit, address, email, notes, lines, subtotal, shipping: hasShipping ? shippingAmt : null, tax_rate: hasTax ? taxRate : null, tax_amount: hasTax ? taxAmt : null, total, level: window._editOrderLevel || 'Salon', payment_method: document.getElementById('edit-payment-method')?.value || null })
    });
    closeEditModal();
    showToast('✓ Orden actualizada');
    await loadOrders();
  } catch(e) {
    showToast('❌ Error al guardar');
    console.error(e);
  } finally {
    btn.disabled = false;
    btn.textContent = 'Guardar cambios →';
  }
}

